97	    ) {
98	        if !output_selection.is_object() {
99	            *output_selection = serde_json::json!({});
100	        }
101	
102	        let file_entry = output_selection
103	            .as_object_mut()
104	            .unwrap()
105	            .entry(file_selector.to_owned())
106	            .or_insert_with(|| serde_json::json!({}));
107	        if !file_entry.is_object() {
108	            *file_entry = serde_json::json!({});
109	        }
110	
111	        let contract_entry = file_entry
112	            .as_object_mut()
113	            .unwrap()
114	            .entry(contract_selector.to_owned())
115	            .or_insert_with(|| serde_json::json!([]));
116	        if !contract_entry.is_array() {
117	            *contract_entry = serde_json::json!([]);
118	        }
119	
120	        let selected_outputs = contract_entry.as_array_mut().unwrap();
121	        for output in outputs {
122	            if !selected_outputs
123	                .iter()
124	                .any(|value| value.as_str() == Some(output))
125	            {
126	                selected_outputs.push(serde_json::Value::String((*output).to_owned()));
127	            }
128	        }
129	    }
