38	        req: VerificationIncomingRequest,
39	    ) -> Result<SolcInput, ContractVerifierError> {
40	        let (file_name, contract_name) = process_contract_name(&req.contract_name, "sol");
41	        let default_output_selection = serde_json::json!({
42	            "*": {
43	                "*": [ "abi", "evm.bytecode", "evm.deployedBytecode" ],
44	                 "": [ "abi", "evm.bytecode", "evm.deployedBytecode" ],
45	            }
46	        });
47	
48	        let standard_json = match req.source_code_data {
49	            SourceCodeData::SolSingleFile(source_code) => {
50	                if has_dangerous_imports(&source_code) {
51	                    return Err(ContractVerifierError::InvalidSourcePath(
52	                        "import with absolute path".to_owned(),
53	                    ));
54	                }
55	                let source = Source {
56	                    content: source_code,
57	                };
58	                let sources = HashMap::from([(file_name.clone(), source)]);
59	                let mut settings = Settings {
60	                    output_selection: Some(default_output_selection),
61	                    other: serde_json::json!({
62	                        "optimizer": {
63	                            "enabled": req.optimization_used,
64	                        },
65	                    }),
66	                };
67	                if let Some(runs) = req.evm_specific.optimizer_runs {
68	                    settings.other["optimizer"]["runs"] = serde_json::json!(runs);
69	                }
70	                if let Some(evm_version) = req.evm_specific.evm_version {
71	                    settings.other["evmVersion"] = serde_json::json!(evm_version);
72	                }
73	
74	                StandardJson {
75	                    language: "Solidity".to_owned(),
76	                    sources,
77	                    other: serde_json::json!({}),
78	                    settings,
79	                }
80	            }
81	            SourceCodeData::StandardJsonInput(map) => {
82	                let mut compiler_input: StandardJson =
83	                    serde_json::from_value(serde_json::Value::Object(map))
84	                        .map_err(|_| ContractVerifierError::FailedToDeserializeInput)?;
85	                validate_source_paths(&compiler_input.sources)?;
86	                for source in compiler_input.sources.values() {
87	                    if has_dangerous_imports(&source.content) {
88	                        return Err(ContractVerifierError::InvalidSourcePath(
89	                            "import with absolute path".to_owned(),
90	                        ));
91	                    }
92	                }
93	                // Set default output selection even if it is different in request.
94	                compiler_input.settings.output_selection = Some(default_output_selection);
95	                compiler_input
96	            }
97	            SourceCodeData::YulSingleFile(source_code) => {
98	                let source = Source {
99	                    content: source_code,
100	                };
101	                let sources = HashMap::from([(file_name.clone(), source)]);
102	                let settings = Settings {
103	                    output_selection: Some(default_output_selection),
104	                    other: serde_json::json!({
105	                        "optimizer": {
